    tw = b.their_playable_wins
    if len(mw) >= 2:
        return True
    if len(mw) == 1 and (b.ply >= 18 or stacked(b.my_wins, mw)):
        return True
    if len(mw) == 0 and len(tw) >= 2:
        return True
    return False

