        return 0
    if len(mw) == 0:
        return 4
    if b.ply >= 24:
        return 9
    return 7

def stacked_cols(b, wins):
    # columns where two vertically adjacent empty cells (at or above the landing cell) both win for one side
    out = []
    for c in range(7):
        lr = b.landing(c)
        if lr is None:
            continue
        for r in range(lr, 5):
            if (r, c) in wins and (r + 1, c) in wins:
                out.append((r - lr, c))
                break
    return out

def fires(b):
    return level(b) >= 5

